def solve(g):
    Hh,Ww=len(g),len(g[0])
    rs=bands([r for r in range(Hh) if all(x==8 for x in g[r])],Hh)
    cs=bands([c for c in range(Ww) if all(g[r][c]==8 for r in range(Hh))],Ww)
    rc_={}; cc={}
    for r in range(Hh):
        for c in range(Ww):
            v=g[r][c]
            if v in (0,8): continue
            ri=next(i for i,(a,b) in enumerate(rs) if a<=r<=b)
            ci=next(i for i,(a,b) in enumerate(cs) if a<=c<=b)
            rc_.setdefault(ri,set()).add(v); cc.setdefault(ci,set()).add(v)
    out=[r[:] for r in g]
    for ri,(ra,rb0) in enumerate(rs):
        for ci,(ca,cb0) in enumerate(cs):
            rr=list(rc_.get(ri,[])); xx=list(cc.get(ci,[]))
            if not rr and not xx: continue
            m = rr[0]*xx[0] if rr and xx else (rr[0] if rr else xx[0])
            for r2 in range(ra,rb0+1):
                for c2 in range(ca,cb0+1):
                    if g[r2][c2]==0: out[r2][c2]=m
    return out
